-- ============================================================================
-- Migration Metadata (for schema versioning)
-- ============================================================================
-- Deferred FK constraints to resolve forward references in table creation order
ALTER TABLE ml_artifacts.solar_panels
    ADD CONSTRAINT fk_string FOREIGN KEY (string_id)
        REFERENCES ml_artifacts.panel_strings(string_id) ON DELETE SET NULL;

ALTER TABLE ml_artifacts.panel_strings
    ADD CONSTRAINT fk_inverter_group FOREIGN KEY (inverter_group_id)
        REFERENCES ml_artifacts.inverter_groups(inverter_group_id) ON DELETE SET NULL;

